def suggested_products(products, search_word):
    products.sort()
    root = {'children': {}, 'suggestions': []}

    for product in products:
        node = root
        for ch in product:
            node = node['children'].setdefault(ch, {'children': {}, 'suggestions': []})
            if len(node['suggestions']) < 3:
                node['suggestions'].append(product)

    result = []
    node = root
    fell_off = False
    for ch in search_word:
        if fell_off or ch not in node['children']:
            fell_off = True
            result.append([])
            continue
        node = node['children'][ch]
        result.append(node['suggestions'])

    return result

